import{_ as o,o as t,c as n,aj as r}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Migrations","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/migrations.md","filePath":"en/reference/migrations.md"}'),i={name:"en/reference/migrations.md"};function a(s,e,l,c,d,g){return t(),n("div",null,e[0]||(e[0]=[r('<h1 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h1><p>Learn about how you can migrate your existing angular project to the latest features incrementally.</p><ul><li><a href="/en/reference/migrations/standalone"><strong>Standalone</strong></a>: Standalone components provide a simplified way to build Angular applications. Standalone components specify their dependencies directly instead of getting them through NgModules.</li><li><a href="/en/reference/migrations/control-flow"><strong>Control Flow Syntax</strong></a>: Built-in Control Flow Syntax allows you to use more ergonomic syntax which is close to JavaScript and has better type checking. It replaces the need to import <code>CommonModule</code> to use functionality like <code>*ngFor</code>, <code>*ngIf</code> and <code>*ngSwitch</code>.</li><li><a href="/en/reference/migrations/inject-function"><strong>inject() Function</strong></a>: Angular&#39;s <a href="https://angular.dev/api/core/inject" target="_blank" rel="noreferrer"><code>inject</code></a> function offers more accurate types and better compatibility with standard decorators, compared to constructor-based injection.</li><li><a href="/en/reference/migrations/route-lazy-loading"><strong>Lazy-loaded routes</strong></a>: Convert eagerly loaded component routes to lazy loaded ones. This allows the build process to split production bundles into smaller chunks, to load less JavaScript at initial page load.</li><li><a href="/en/reference/migrations/signal-inputs"><strong>New <code>input()</code> API</strong></a>: Convert existing <code>@Input</code> fields to the new signal input API that is now production ready.</li><li><a href="/en/reference/migrations/outputs"><strong>New <code>output()</code> function</strong></a>: Convert existing <code>@Output</code> custom events to the new output function that is now production ready.</li><li><a href="/en/reference/migrations/signal-queries"><strong>Queries as signal</strong></a>: Convert existing decorator query fields to the improved signal queries API. The API is now production ready.</li><li><a href="/en/reference/migrations/cleanup-unused-imports"><strong>Cleanup unused imports</strong></a>: Clean up unused imports in your project.</li><li><a href="/en/reference/migrations/self-closing-tags"><strong>Self-closing tags</strong></a>: Convert component templates to use self-closing tags where possible.</li><li><a href="/en/reference/migrations/ngclass-to-class"><strong>NgClass to Class Bindings</strong></a>: Convert component templates to prefer class bindings over the <code>NgClass</code> directives when possible.</li><li><a href="/en/reference/migrations/ngstyle-to-style"><strong>NgStyle to Style Bindings</strong></a>: Convert component templates to prefer style bindings over the <code>NgStyle</code> directives when possible.</li><li><a href="/en/reference/migrations/router-testing-module-migration"><strong>RouterTestingModule migration</strong></a>: Convert <code>RouterTestingModule</code> usages to <code>RouterModule</code> in TestBed configurations and add <code>provideLocationMocks()</code> when appropriate.</li><li><a href="/en/reference/migrations/common-to-standalone"><strong>CommonModule to standalone imports</strong></a>: Replace imports of the <code>CommonModule</code> with imports of the individual directives and pipes used in the templates when possible.</li><li><a href="/en/reference/migrations/injectable-to-service"><strong>Injectable to Service</strong></a>: Convert eligible <code>@Injectable</code> classes to the <code>@Service</code> decorator.</li></ul>',3)]))}const m=o(i,[["render",a]]);export{p as __pageData,m as default};
